package com.appropriate.riskauditor.core.model

/**
 * An evidence-backed security finding generated by the local risk engine.
 *
 * PS-01 Requirement: Every High or Critical result must be supported by
 * at least three distinct, evidence-backed findings with actionable recommendations.
 */
data class RiskFinding(
    val ruleId: String,
    val title: String,
    val severity: FindingSeverity,
    val points: Int,
    val category: RiskCategory,
    val evidence: String,
    val explanation: String,
    val confidence: FindingConfidence,
    val recommendation: String
)
